	{"id": "Stingray.Jazz.Latino", "n": "Jazz Latino", "t": "Jazz Latino", "g": "Stingray Music", "i": "https://music.stingray.com/themes/custom/music/images/Stingray-Music-MetaImage-en.png", "d": "Recopilando lo mejor del Jazz latino, la bossa nova y el jazz afro-cubano siempre con un toque de improvisación."},
	{"id": "Stingray.Jazz.Moderno", "n": "Jazz Moderno", "t": "Jazz Moderno", "g": "Stingray Music", "i": "https://music.stingray.com/themes/custom/music/images/Stingray-Music-MetaImage-en.png", "d": "Un espacio para oír el mundo actual del Jazz."},
	{"id": "Stingray.Las.Mujeres.en.la.Musica", "n": "Las Mujeres en la Música", "t": "Las Mujeres en la Música", "g": "Stingray Music", "i": "https://music.stingray.com/themes/custom/music/images/Stingray-Music-MetaImage-en.png", "d": "Celebra a las mujeres que han sabido romper barreras, sobresalir e ir más allá de lo esperado. Escucha sus mayores éxitos incluyendo todos los géneros, épocas y estilos de vida."},
	{"id": "Stingray.Latin.Lounge", "n": "Latin Lounge", "t": "Latin Lounge", "g": "Stingray Music", "i": "https://music.stingray.com/themes/custom/music/images/Stingray-Music-MetaImage-en.png", "d": "Sonidos sofisticados y ambiente relajado para celebrar los placeres de la vida."},
	{"id": "Stingray.Maestros.del.Clasico", "n": "Maestros del Clásico", "t": "Maestros del Clásico", "g": "Stingray Music", "i": "https://music.stingray.com/themes/custom/music/images/Stingray-Music-MetaImage-en.png", "d": "Lo sofisticado, lo estimulante y arrebatador. Maestros del Clásico te trae conciertos, sinfonías y música de Ballet desde 1760 hasta ahora. Desde Bach hasta Bartok y Stravinsky, con énfasis en Haydn, Mozart, Beethoven, Schubert, Schumann, Brahms, Dvorak y otros."},
	{"id": "Stingray.Maestros.del.Jazz", "n": "Maestros del Jazz", "t": "Maestros del Jazz", "g": "Stingray Music", "i": "https://music.stingray.com/themes/custom/music/images/Stingray-Music-MetaImage-en.png", "d": "La contribución de los Estados Unidos a la música moderna. Los maestros del Jazz que dieron forma a este fantástico género musical. Desde Ellington y Gillespie a Miles Davis, MJQ y cantantes populares como Billie Holiday, Ella Fitzgerald y Frank Sinatra. Estos son los íconos pioneros del Jazz."},
	{"id": "Stingray.Mariachi.y.Ranchera", "n": "Mariachi y Ranchera", "t": "Mariachi y Ranchera", "g": "Stingray Music", "i": "https://music.stingray.com/themes/custom/music/images/Stingray-Music-MetaImage-en.png", "d": "Celebra la tradición mexicana con lo mejor del mariachi y la ranchera."},
	{"id": "Stingray.MPB.(Musica.Popular.Brasileña)", "n": "MPB (Música Popular Brasileña)", "t": "MPB (Música Popular Brasileña)", "g": "Stingray Music", "i": "https://music.stingray.com/themes/custom/music/images/Stingray-Music-MetaImage-en.png", "d": "Sonidos suaves procedentes de Brasil. El canal ofrece una mezcla sensual de \"Música Popular Brasilera\", con artistas que van de la bossa-nova de los años 60 a la actual generación de artistas \"Nueva MPB\". Sonidos acústicos y electrónicos, buenas letras y ritmos atemporales hacen de este canal el lugar perfecto para escapar de la realidad."},
	{"id": "Stingray.Musica.del.Mundo", "n": "Música del Mundo", "t": "Música del Mundo", "g": "Stingray Music", "i": "https://music.stingray.com/themes/custom/music/images/Stingray-Music-MetaImage-en.png", "d": "Explora sonidos y tradiciones de todos los rincones del planeta."},
